import{_ as a,o as l,c as i,a2 as t}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"CephFS Code Walkthrough- kclient overview","description":"","frontmatter":{"title":"CephFS Code Walkthrough- kclient overview","date":"2021-12-06T00:00:00.000Z","updated":"2021-12-07T00:00:00.000Z","tags":["Ceph","分布式存储","k客户端","内核组件","文件系统"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2021/CephFS_Code_Walkthrough_-_kclient_overview.md","filePath":"posts/2021/CephFS_Code_Walkthrough_-_kclient_overview.md","lastUpdated":1780459816000}'),r={name:"posts/2021/CephFS_Code_Walkthrough_-_kclient_overview.md"};function o(h,e,s,n,p,d){return l(),i("div",null,[...e[0]||(e[0]=[t('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph客户端代码概述" tabindex="-1">会议主题：Ceph客户端代码概述 <a class="header-anchor" href="#会议主题-ceph客户端代码概述" aria-label="Permalink to &quot;会议主题：Ceph客户端代码概述&quot;">​</a></h4><h4 id="会议时间-具体时间" tabindex="-1">会议时间：[具体时间] <a class="header-anchor" href="#会议时间-具体时间" aria-label="Permalink to &quot;会议时间：[具体时间]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="参会人员-参会人员名单" tabindex="-1">参会人员：[参会人员名单] <a class="header-anchor" href="#参会人员-参会人员名单" aria-label="Permalink to &quot;参会人员：[参会人员名单]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>Ceph客户端代码概述</strong></p><ul><li>演讲者简要介绍了Ceph客户端（k client）的代码结构，强调了其与用户空间客户端的区别，主要在于共享的只是一些头文件。</li><li>详细介绍了内核中的几个关键组件，包括libsep（内核模块，作为Ceph的底层传输层）、rbd驱动（主要调用libsep实现）和cephfs代码所在的fsf。</li></ul></li><li><p><strong>内核组件详细介绍</strong></p><ul><li><strong>libsep</strong>：作为Ceph代码在内核中的传输层，主要代码位于netsef目录下，包含处理认证、加密、消息传递（v1和v2版本）等功能。</li><li><strong>rbd驱动</strong>：虽然代码量不大，但负责调用libsep实现路由块设备的功能。</li><li><strong>cephfs代码</strong>：位于fsf目录下，是一个完整的分布式文件系统（DFS）层内核驱动，负责创建块设备驱动并与libsep交互以与各种守护进程通信。</li></ul></li><li><p><strong>文件系统操作流程</strong></p><ul><li>讨论了文件系统的挂载、文件打开和写操作的流程，包括路径遍历、原子打开操作、写请求的处理以及同步写操作的细节。</li><li>强调了vfs层和cephfs客户端之间的交互，以及如何处理用户驱动的系统调用事件。</li></ul></li><li><p><strong>后台自动处理活动</strong></p><ul><li>提到了一些后台自动处理的活动，如连接的调度例程、cap消息的处理等，这些活动由mds驱动。</li><li>详细解释了cap消息的处理流程，包括cap的授予和撤销，以及如何处理这些操作引发的写回操作。</li></ul></li><li><p><strong>问题与讨论</strong></p><ul><li>会议中涉及了一些技术问题，如页面写回错误处理、reader plus操作的使用等，演讲者对这些问题进行了详细的解答。</li><li>讨论了reader plus操作的实际应用场景和潜在的性能提升，以及为何该操作在某些情况下可能不如预期有效。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项： <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项：&quot;">​</a></h4><ul><li>无具体决定事项，主要是技术分享和讨论。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>继续优化Ceph客户端代码，特别是libsep中的序列化问题，以提高性能。</li><li>探索和实施新的I/O操作方式，如iou ring，以进一步提升性能和效率。</li></ul><h4 id="备注" tabindex="-1">备注： <a class="header-anchor" href="#备注" aria-label="Permalink to &quot;备注：&quot;">​</a></h4><ul><li>会议内容主要针对Ceph客户端代码的技术细节，适合对Ceph有深入了解的开发人员。</li></ul><h4 id="会议结束语" tabindex="-1">会议结束语： <a class="header-anchor" href="#会议结束语" aria-label="Permalink to &quot;会议结束语：&quot;">​</a></h4><ul><li>演讲者感谢大家的参与，并祝愿大家有一个愉快的一天。</li></ul>',15)])])}const _=a(r,[["render",o]]);export{c as __pageData,_ as default};
